<?php

declare(strict_types=1);

namespace Intrabase\Modules\Sys;

use Intrabase\Core\Module;

/**
 * sys_notifications — System Notifications
 *
 * Manages system notifications sent to users programmatically.
 * Notifications cannot be created manually through the UI; they are
 * generated by system events. Users can mark them as read.
 *
 * onPreSave: if is_read=1 and read_at is empty, auto-sets read_at to now.
 *
 * Table: ib_sys_notifications
 */
class SysNotifications extends Module
{
    public string $table = 'ib_sys_notifications';

    /** Dades personals: la interficie web nomes mostra les files propies. */
    public bool $scopeUiByOwner = true;
    public ?string $apiScopeByEntity = 'entity_id';
    public ?string $apiScopeByUser   = 'user_id';

    public string $key   = 'id';
    public string $title = 'Notifications';
    public string $icon  = 'fa-solid fa-bell';

    public array $fields = [
        'id',
        'title',
        'user_id',
        'notification_type',
        'is_read',
        'created_at',
    ];

    public array $showFields = [
        'user_id',
        'notification_type',
        'title',
        'message',
        'url',
        'icon_class',
        'is_read',
        'read_at',
        'expires_at',
        'created_at',
        'updated_at',
    ];

    public array $editFields = [
        'user_id',
        'notification_type',
        'title',
        'message',
        'url',
        'icon_class',
        'is_read',
        'read_at',
        'expires_at',
    ];

    public array $searchFields = ['title', 'message'];

    public array $humans = [
        'id'                => 'ID',
        'user_id'           => 'User',
        'notification_type' => 'Type',
        'title'             => 'Title',
        'message'           => 'Message',
        'url'               => 'URL',
        'icon_class'        => 'Icon Class',
        'is_read'           => 'Read',
        'read_at'           => 'Read At',
        'expires_at'        => 'Expires At',
        'created_at'        => 'Created',
        'updated_at'        => 'Updated',
    ];

    public array $components = [
        'notification_type' => 'select',
        'message'           => 'textarea',
        'is_read'           => 'select',
        'read_at'           => 'datetime',
        'expires_at'        => 'datetime',
        'created_at'        => 'datetime',
        'updated_at'        => 'datetime',
    ];

    public array $selects = [
        'notification_type' => [
            'info'    => 'Info',
            'warning' => 'Warning',
            'success' => 'Success',
            'danger'  => 'Danger',
            'system'  => 'System',
        ],
        'is_read' => [
            '1' => 'Read',
            '0' => 'Unread',
        ],
    ];

    /** Only is_read is editable; all other fields are readonly */
    public array $readonly = [
        'user_id',
        'notification_type',
        'title',
        'message',
        'url',
        'icon_class',
        'read_at',
        'expires_at',
        'created_at',
        'updated_at',
    ];

    public array $validates = ['title', 'notification_type'];

    public string $orderBy  = 'created_at';
    public string $orderDir = 'DESC';

    public bool $canAdd    = false;
    public bool $canEdit   = true;
    public bool $canDelete = true;
    public bool $canExport = true;

    public function __construct(mixed ...$args)
    {
        parent::__construct(...$args);

        $this->defaultValues['is_read']           = '0';
        $this->defaultValues['notification_type'] = 'info';
        $this->defaultValues['icon_class']        = 'fa-solid fa-bell';

        $this->combos['user_id'] = [
            'table'      => 'ib_users',
            'key'        => 'id',
            'label'      => 'username',
            'orderBy'    => 'username ASC',
            'allowEmpty' => true,
        ];

        $this->advancedFilters = [
            [
                'field'      => 'user_id',
                'label'      => 'User',
                'type'       => 'combo',
                'table'      => 'ib_users',
                'key'        => 'id',
                'label_col'  => 'username',
            ],
            [
                'field'   => 'notification_type',
                'label'   => 'Type',
                'type'    => 'select',
                'options' => [
                    ''        => 'All',
                    'info'    => 'Info',
                    'warning' => 'Warning',
                    'success' => 'Success',
                    'danger'  => 'Danger',
                    'system'  => 'System',
                ],
            ],
            [
                'field'   => 'is_read',
                'label'   => 'Read',
                'type'    => 'combo',
                'options' => [
                    ''  => 'All',
                    '1' => 'Read',
                    '0' => 'Unread',
                ],
            ],
            [
                'field' => 'created_at',
                'label' => 'Created',
                'type'  => 'date_range',
            ],
        ];
    }

    /**
     * If marking as read and read_at not yet set, auto-populate read_at.
     */
    public function onPreSave(array &$data): bool
    {
        $isCreate = !isset($data[$this->key]) || (int) $data[$this->key] === 0;
        if (isset($data['is_read']) && (int)$data['is_read'] === 1 && empty($data['read_at'])) {
            $data['read_at'] = date('Y-m-d H:i:s');
        }

        return true;
    }
}
